from pathlib import Path
import sys,json,gzip,hashlib,math,csv
import numpy as np
import torch
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
r=Path.cwd();sys.path.insert(0,str(r/'scripts/reinforcement_learning/rsl_rl'))
from policy_evaluation_evidence import validate_evaluation_bundle
import diagnose_motion_policy_symmetry as diag
torch.set_num_threads(2)
root=r/'learnings/policy_tuning/RobotLab-Isaac-BeyondMimic-Flat-LW-wheel-v0'
runs={'old':'2026-11-05_16-40-14','new':'2026-11-06_11-39-51'}
batch={'old':'wheel-to-leg-fixed-start-20261106-001','new':'wheel-to-leg-fixed-start-20261107-001'}
out=root/runs['new']/'evaluations'/batch['new']/'derived';out.mkdir(exist_ok=True)
ref=lambda p:{'path':str(p),'sha256':hashlib.sha256(Path(p).read_bytes()).hexdigest()}
rms=lambda x:float(np.sqrt(np.mean(np.asarray(x)**2)))
stats={};datasets={};inputs=[];curves={};jointrows=[];couplingrows=[];fkerr=0
def rpy(q):
 q=np.asarray(q);q=q/np.linalg.norm(q,axis=-1,keepdims=True);w,x,y,z=np.moveaxis(q,-1,0)
 return np.stack([np.arctan2(2*(w*x+y*z),1-2*(x*x+y*y)),np.arcsin(np.clip(2*(w*y-z*x),-1,1)),np.arctan2(2*(w*z+x*y),1-2*(y*y+z*z))],axis=-1)
def rot(q,v):
 q=np.asarray(q);q=q/np.linalg.norm(q);v=np.asarray(v);t=2*np.cross(q[1:],v);return v+q[0]*t+np.cross(q[1:],t)
def summarize_values(v):
 return {'mean':float(np.mean(v)),'min':float(np.min(v)),'max':float(np.max(v))}
for version,run in runs.items():
 stats[version]={}
 for case in ['nominal','randomized']:
  directory=root/run/'evaluations'/batch[version]/'raw'/('fixed-start-'+case+'-a01')
  validate_evaluation_bundle(directory/'result.json');res=json.loads((directory/'result.json').read_text())
  with gzip.open(directory/'telemetry.json.gz','rt') as f:t=json.load(f)
  assert t['telemetry_status']=='complete' and not t['missing_required_signals']
  datasets[version,case]=t
  inputs.extend(ref(directory/n) for n in ['result.json','telemetry.json.gz'])
  samples=t['samples'];ps=t['physics_samples'];md=t['motion_diagnostics'];names=t['joint_names'];bn=md['body_names'];rt=md['initial_runtime']
  assert len(samples)==1000 and len(ps)==4000
  arr=lambda name:np.asarray([s[name] for s in samples],dtype=float)
  parr=lambda name:np.asarray([s[name] for s in ps],dtype=float)
  f=arr('frame_index').astype(int);ts=f/50;time=ts+.02;eps=arr('episode_id').astype(int)
  angle=np.degrees(rpy(arr('root_quaternion_w')));z=arr('root_position_w')[:,2];refz=arr('reference_body_position_w').reshape(-1,len(bn),3)[:,bn.index('base_link'),2]
  take=(ts>=1.1)&(ts<=1.7);land=(ts>=1.45)&(ts<=1.9);pre=(time>=1.1)&(time<=1.38)
  v=parr('joint_velocity');tau=parr('applied_torque');ctau=parr('computed_torque');pt=np.array([p['frame_index']/50+(p['substep']+1)*.005 for p in ps]);pe=np.array([p['episode_id'] for p in ps])
  forces=parr('contact_forces_w').reshape(-1,4,3);ground=parr('ground_contact_forces_w').reshape(-1,4,3);fz=forces[:,:,2]
  effort=np.asarray(t['joint_effort_limits']);limits=np.array([33 if 'wheel' in n else 10 if 'foot' in n else 20 for n in names])
  per=[]
  for j,n in enumerate(names):
   mask=np.abs(v[:,j])>limits[j]+1e-5; sat=np.abs(tau[:,j])>=effort[j]*(1-1e-6)
   rec={'version':version,'case':case,'joint':n,'velocity_peak_rad_s':float(np.max(np.abs(v[:,j]))),'velocity_rms_rad_s':rms(v[:,j]),'nominal_velocity_limit_rad_s':float(limits[j]),'overspeed_total_ms':int(mask.sum())*5,'torque_peak_nm':float(np.max(np.abs(tau[:,j]))),'torque_rms_nm':rms(tau[:,j]),'effort_limit_nm':float(effort[j]),'saturation_total_ms':int(sat.sum())*5}
   jointrows.append(rec);per.append(rec)
  per_episode=[]
  q=arr('joint_position');qref=arr('reference_joint_position');dq=arr('joint_velocity');dqref=arr('reference_joint_velocity')
  li=names.index('left_hip_joint');ri=names.index('right_hip_joint');hipcommon=np.degrees((q[:,li]+q[:,ri]-qref[:,li]-qref[:,ri])/2)
  asym={}
  for part in ['hip','thigh','shank','foot','wheel']:
   l=names.index('left_'+part+'_joint');rr=names.index('right_'+part+'_joint')
   asym[part]={'velocity_mirror_residual_rms_rad_s':rms(v[:,l]+v[:,rr]),'torque_mirror_residual_rms_nm':rms(tau[:,l]+tau[:,rr]),'position_ref_relative_pair_rms_deg':rms(np.degrees(q[:,l]+q[:,rr]-qref[:,l]-qref[:,rr])) if part!='wheel' else None,'velocity_ref_relative_pair_rms_rad_s':rms(dq[:,l]+dq[:,rr]-dqref[:,l]-dqref[:,rr])}
  phys={(p['episode_id'],p['frame_index']):p for p in ps}
  comvals=np.full(len(samples),np.nan);basevals=np.full(len(samples),np.nan)
  for k,s in enumerate(samples):
   if not pre[k] or s['done']:continue
   p=phys[(s['episode_id'],s['frame_index'])];assert p['substep']==3 and abs(p['sim_time_seconds']-s['sim_time_seconds'])<1e-5
   bp=np.asarray(s['body_position_w']).reshape(-1,3);bq=np.asarray(s['body_quaternion_w']).reshape(-1,4);wheels=np.asarray(p['wheel_center_position_w']).reshape(2,3);poses={n:(bp[i],bq[i]) for i,n in enumerate(bn)}
   for wi,side in enumerate(['right','left']):
    n=side+'_wheel_link';sh=bn.index(side+'_shank_link');c=np.asarray(rt['coms'])[rt['body_names'].index(n),:3];assert abs(c[0])+abs(c[2])<1e-8
    expected=bp[sh]+rot(bq[sh],[-.183850,-.061 if side=='right' else .061,-.183850]);fkerr=max(fkerr,float(np.linalg.norm(expected-wheels[wi])));poses[n]=(wheels[wi],bq[sh])
   center=sum(m*(poses[n][0]+rot(poses[n][1],c[:3])) for m,n,c in zip(rt['masses_kg'],rt['body_names'],rt['coms']))/sum(rt['masses_kg'])
   yaw=np.radians(angle[k,2]);lateral=np.array([-math.sin(yaw),math.cos(yaw),0]);mid=wheels.mean(0)
   comvals[k]=float((center-mid)@lateral*100);basevals[k]=float((arr('root_position_w')[k]-mid)@lateral*100)
   couplingrows.append({'version':version,'case':case,'episode':int(eps[k]),'time_s':float(time[k]),'hip_common_error_deg':float(hipcommon[k]),'roll_deg':float(angle[k,0]),'com_lateral_from_wheel_midpoint_cm':float(comvals[k]),'base_lateral_from_wheel_midpoint_cm':float(basevals[k])})
  for ep in sorted(set(eps)):
   mask=eps==ep;tp=take&mask;lp=land&mask;epm=pe==ep
   terminal=[s for s in samples if s['episode_id']==ep and s['done']]
   rec={'episode':int(ep),'complete':bool(terminal),'successful':bool(terminal and terminal[-1]['termination_terms']['motion_finished'] and not any(x for n,x in terminal[-1]['termination_terms'].items() if n!='motion_finished')),'jump_peak_z_m':float(z[tp].max()),'jump_peak_frame_time_s':float(ts[np.where(tp)[0][np.argmax(z[tp])]]),'reference_jump_peak_z_m':float(refz[tp].max()),'landing_z_at_reference_1p54_m':float(z[mask&(f==77)][0]),'reference_z_at_1p54_m':float(refz[mask&(f==77)][0]),'landing_min_z_m':float(z[lp].min()),'takeoff_roll_max_abs_deg':float(np.max(np.abs(angle[tp,0]))),'hip_common_peak_abs_deg':float(np.max(np.abs(hipcommon[pre&mask]))),'com_lateral_peak_abs_cm':float(np.nanmax(np.abs(comvals[mask]))),'unloading':{}}
   ei=np.where(epm)[0];et=pt[epm];ef=fz[epm];eg=ground[epm,:,2]
   for threshold in [1,10,20]:
    off=np.all(np.concatenate([ef,eg],axis=1)<threshold,axis=1);candidates=[i for i in range(len(et)-2) if 1.15<=et[i]<=1.6 and off[i:i+3].all()]
    if candidates:
     i=candidates[0];times=[]
     for wi in (2,3):
      prev=np.where((et<=et[i])&(ef[:,wi]>=threshold))[0];j=prev[-1]+1 if len(prev) else 0;times.append(float(et[j]))
     rec['unloading'][str(threshold)]={'right_s':times[0],'left_s':times[1],'left_minus_right_ms':round((times[1]-times[0])*1000,5),'all_eight_below_s':float(et[i])}
    else:rec['unloading'][str(threshold)]=None
   per_episode.append(rec)
  stats[version][case]={'metrics':res['metrics'],'telemetry_complete':True,'physics_samples':len(ps),'roll_max_abs_deg_all':float(np.max(np.abs(angle[:,0]))),'takeoff_roll_max_abs_deg':float(np.max(np.abs(angle[take,0]))),'landing_pitch_max_abs_deg':float(np.max(np.abs(angle[land,1]))),'jump_peak_z_m':summarize_values([x['jump_peak_z_m'] for x in per_episode]),'landing_z_at_reference_1p54_m':summarize_values([x['landing_z_at_reference_1p54_m'] for x in per_episode]),'landing_z_error_rmse_m':rms((z-refz)[land]),'takeoff_hip_common_peak_abs_deg':float(np.max(np.abs(hipcommon[pre]))),'takeoff_com_lateral_peak_abs_cm':float(np.nanmax(np.abs(comvals))),'unload_lag_ms':summarize_values([x['unloading']['10']['left_minus_right_ms'] for x in per_episode if x['unloading']['10']]),'foot_force_peak_n':float(np.linalg.norm(forces[:,:2],axis=2).max()),'wheel_force_peak_n':float(np.linalg.norm(forces[:,2:],axis=2).max()),'ground_contact_peak_n':float(np.linalg.norm(ground,axis=2).max()),'asymmetry':asym,'joint_loads':per,'episodes':per_episode}
  curves[version,case]={'t':ts,'z':z,'refz':refz,'roll':angle[:,0],'hipcommon':hipcommon,'eps':eps}
# Compare both frozen actors on the identical observation sets, avoiding a state-distribution explanation.
actors={};envs={}
for version,run in runs.items():
 runpath=r/'logs/rsl_rl/LW_wheel_beyongdmimic'/run
 envs[version]=diag.read_config(runpath/'params/env.yaml');cfg=diag.read_config(runpath/'params/agent.yaml');actors[version]=diag.load_actor(runpath/'model_49999.pt',cfg)[0]
 inputs.extend([ref(runpath/'model_49999.pt'),ref(runpath/'params/env.yaml'),ref(runpath/'params/agent.yaml')])
shared={}
for source in runs:
 t=datasets[source,'nominal'];motion=np.load(t['motion_diagnostics']['motion_file']['path']);obs,recorded,labels=diag.reconstruct_observations(t,motion,envs[source]);shared[source]={}
 for version,actor in actors.items():
  diagnostic,err,pred=diag.diagnose(actor,obs,recorded,labels,exact=version==source,replay_atol=1e-4)
  shared[source][version]={k:diagnostic[k] for k in ['input_semantics','recorded_action_comparison','all','phases']}
# Statistical plots retain cycle variation; nominal repeated cycles are not independent trials.
fig,axs=plt.subplots(3,2,figsize=(12,10),sharex=True)
for col,case in enumerate(['nominal','randomized']):
 for version,color in [('old','tab:orange'),('new','tab:blue')]:
  c=curves[version,case]
  for ep in sorted(set(c['eps'])):
   m=(c['eps']==ep)&(c['t']>=.9)&(c['t']<=1.95)
   for row,key in enumerate(['z','roll','hipcommon']):axs[row,col].plot(c['t'][m],c[key][m],color=color,alpha=.7 if case=='nominal' else .35,label=version if ep==0 else None)
 c=curves['new',case];m=(c['eps']==0)&(c['t']>=.9)&(c['t']<=1.95);axs[0,col].plot(c['t'][m],c['refz'][m],'k--',label='reference')
 for row,label in enumerate(['Base height (m)','Roll (deg)','Hip common error (deg)']):
  axs[row,col].set_ylabel(label);axs[row,col].grid(alpha=.25)
 axs[0,col].set_title(case);axs[0,col].legend();axs[2,col].set_xlabel('Commanded reference time (s)')
fig.tight_layout();fig.savefig(out/'phase-comparison.png',dpi=160);plt.close(fig)
for name,rows in [('joint-loads.csv',jointrows),('takeoff-coupling.csv',couplingrows)]:
 with (out/name).open('x',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
analysis={'version':1,'inputs':inputs,'source':CODE_SOURCE,'statistics':stats,'shared_observation_mirror_comparison':shared,'wheel_fk_max_error_m':fkerr,'conventions':{'height_roll':'post-physics state labeled with commanded reference frame/fps; jump window 1.1..1.7 s, landing 1.45..1.9 s','coupling':'physical time frame/fps+0.02, preparation 1.1..1.38 s; COM from measured masses/local COMs, relative to wheel midpoint in yaw lateral axis','unloading':'physical substep time; first 15ms all eight monitored contacts below 1/10/20 N in 1.15..1.6 s; final wheel unloading before it; not proof every robot contact absent','joint_loads':'5ms physics samples, configured nominal speed limits and actuator effort limits; no hardware acceptance claim','episodes':'includes truncated sixth cycle for peaks and windows if covered; successes count only terminal motion_finished without other causes','mirror':'shared old/new nominal observation sets; each model validated against its own recorded mean action; randomized diagnosis is separate noise-free nominal-default probe'},'limitations':['One environment and seed42 per case; startup physical parameters fixed across repeated episodes','Mirror behavior and dynamics improvement are distinct; new training run adds height reward; single independently trained pair does not establish robust causal attribution','No approved convergence thresholds or hardware validation']}
assert fkerr<1e-5
with (out/'analysis.json').open('x') as f:json.dump(analysis,f,indent=2,sort_keys=True,allow_nan=False)
print(json.dumps({v:{c:{k:x for k,x in a.items() if k not in ('joint_loads','episodes','asymmetry','metrics')} for c,a in cases.items()} for v,cases in stats.items()},indent=2))
print('SHARED MIRROR',json.dumps({s:{v:{ph:d['position_target_rms_deg'] for ph,d in val['phases'].items()} for v,val in values.items()} for s,values in shared.items()}))
